INSERT INTO sjt1tg (
    koscom_cd
  , ymd
  , close
  , volume
  , value
  , preclose
  , spot_price
  , calc_price
  , change
) VALUES (
    #{sjCd}
  , TO_DATE(REPLACE(#{ymd}, '-', ''), 'YYYYMMDD')
  , #{close, jdbcType=NUMERIC}
  , #{volume, jdbcType=NUMERIC}
  , #{value, jdbcType=NUMERIC}
  , #{preclose, jdbcType=NUMERIC}
  , #{spotPrice, jdbcType=NUMERIC}
  , #{calcPrice, jdbcType=NUMERIC}
  , NVL(#{change, jdbcType=NUMERIC}, #{close, jdbcType=NUMERIC} - #{preclose, jdbcType=NUMERIC})
)

mapper.update:
UPDATE sjt1tg
   SET close      = #{close, jdbcType=NUMERIC}
     , volume     = #{volume, jdbcType=NUMERIC}
     , value      = #{value, jdbcType=NUMERIC}
     , preclose   = #{preclose, jdbcType=NUMERIC}
     , spot_price = #{spotPrice, jdbcType=NUMERIC}
     , calc_price = #{calcPrice, jdbcType=NUMERIC}
     , change     = NVL(#{change, jdbcType=NUMERIC}, #{close, jdbcType=NUMERIC} - #{preclose, jdbcType=NUMERIC})
 WHERE ymd       = TO_DATE(REPLACE(#{ymd}, '-', ''), 'YYYYMMDD')
   AND koscom_cd = #{sjCd}

mapper.delete:
DELETE FROM sjt1tg
 WHERE ymd       = TO_DATE(REPLACE(#{ymd}, '-', ''), 'YYYYMMDD')
